//! W7 golden-fixture harness: Rust MLE vs. the reference `fitdistcp` R package.
//!
//! Loads `tests/golden/mle_golden.json` (generated by `tools/generate_golden.R`
//! from the reference R package `stephenjewson/fitdistcp`) and compares the Rust
//! [`fitdistcp_core::mle::fit`] output for all ten Phase-1 models against the
//! reference values.
//!
//! # Tolerance policy (§7.2)
//!
//! The consolidated, canonical tolerance policy lives in
//! [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md); the summary
//! below is the subset relevant to this harness.
//!
//! Golden comparisons use `rtol = 1e-8`, `atol = 1e-10`:
//! `|a - b| <= atol + rtol * |b|`.
//!
//! The reference MLEs for the DMGS models (Weibull, Gamma, Gumbel, GEV, GPD,
//! GEV-p1) are produced by R's `optim`. The fixtures are generated with a
//! **tightly-converged** `optim` (`reltol = 1e-14`, see `tools/generate_golden.R`)
//! so they represent the true MLE rather than the default Nelder–Mead stopping
//! point. Even so, the Rust BFGS/Newton and R's `optim` stop at slightly
//! different points on the same flat optimum, so for those models the
//! **parameters** are compared with a documented looser tolerance (`OPT_RTOL`)
//! while the **log-likelihood** (the objective, which is well-determined) is
//! compared at the §7.2 tolerance. The closed-form models (norm, expon, lnorm,
//! norm_p1) are compared at the full §7.2 tolerance.
//!
//! # Documented legitimate differences
//!
//! - **gamma**: the reference uses R's `dgamma(scale=)` parameterization, i.e.
//!   `scale = 1/rate`. The Rust model uses `[shape, rate]`. The harness converts
//!   the reference `scale` to `rate = 1/scale` (and the SE by the delta method)
//!   before comparing.
//! - **norm_p1**: two reference quirks. (1) `norm_p1_mlparams` reports the
//!   *uncentered* intercept from `lm(x~t)`, but its `expinfmat` (and hence its
//!   SEs) uses the *centered* predictor `t - mean(t)`. The harness runs Rust with
//!   `t0 = mean(t)` and converts the reference intercept to the centered one.
//!   (2) The reference sigma is the *unbiased* `sd(residuals)` (`n-1`
//!   denominator), not the true MLE `sqrt((n-1)/n) * sd(residuals)`; the harness
//!   converts both the sigma and its SE. The reference's own `ml_value` also uses
//!   the unbiased sigma, so the fixture stores the true-MLE loglik/AIC instead.
//! - **Standard errors of the DMGS models** (weibull, gamma, gumbel, genextreme,
//!   genpareto, genextreme_p1): as of **W9** Rust uses the same *analytic*
//!   second derivatives as the reference, so the SEs now agree to ~1e-7 (the
//!   observed maximum relative residual is `3.5e-6` for genextreme_p1, whose
//!   observed-information matrix is the most ill-conditioned). `SE_RTOL = 1e-5`
//!   is a 100× tightening of the pre-W9 `1e-3`.

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::mle::fit;
use fitdistcp_core::models::{
    Exponential, Gamma, GenExtreme, GenExtremeP1, GenPareto, Gumbel, LogNormal, Normal, NormalP1,
    Weibull,
};

// --- §7.2 golden tolerance --------------------------------------------------
const RTOL: f64 = 1e-8;
const ATOL: f64 = 1e-10;

/// Looser tolerance for optimizer-produced parameters (see module docs).
/// R's `optim` (Nelder–Mead) and the Rust BFGS/Newton converge to the same
/// optimum but stop at different points on a flat surface; `1e-4` relative is
/// far tighter than the optimizer's own convergence tolerance and still catches
/// any genuine model/parameterization bug.
const OPT_RTOL: f64 = 1e-4;
const OPT_ATOL: f64 = 1e-6;

/// Tolerance for standard errors of the DMGS models (see module docs). As of W9
/// both the reference and Rust use analytic second derivatives, so the SEs agree
/// to ~1e-7; the observed maximum relative residual is `3.5e-6` (genextreme_p1).
/// `1e-5` is a 100× tightening of the pre-W9 `1e-3` and still catches any
/// genuine SE bug (e.g. a wrong sign or a missing factor of n).
const SE_RTOL: f64 = 1e-5;
const SE_ATOL: f64 = 1e-8;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------
//
// The fixture schema is small and fixed, so a tiny recursive-descent parser is
// sufficient and keeps the core crate dependency-free.

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'u' => {
                            let hex = std::str::from_utf8(&self.bytes[self.pos + 1..self.pos + 5])
                                .expect("utf8 hex");
                            let code = u32::from_str_radix(hex, 16).expect("hex");
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            self.pos += 4;
                        }
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    // Copy one UTF-8 byte; multi-byte sequences are copied
                    // verbatim since we only ever emit ASCII keys/notes.
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "mle_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

/// Compare a Rust parameter vector to the reference, element-wise.
fn compare_params(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, model: &str) {
    assert_eq!(
        actual.len(),
        expected.len(),
        "{model}: parameter count mismatch"
    );
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{model} param[{i}]"));
    }
}

#[test]
fn golden_mle_all_models() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");

    let y_general = datasets.get("y_general").as_f64_vec();
    let y_positive = datasets.get("y_positive").as_f64_vec();
    let t_p1 = datasets.get("t_p1").as_f64_vec();

    // --- norm (closed form) -------------------------------------------------
    {
        let m = models.get("norm");
        let r = fit(&Normal::new(), &y_general, &[10.0, 1.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            RTOL,
            ATOL,
            "norm",
        );
        compare_params(&r.ml_se, &m.get("se").as_f64_vec(), RTOL, ATOL, "norm.se");
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "norm.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "norm.loglik",
        );
    }

    // --- expon (closed form) ------------------------------------------------
    {
        let m = models.get("expon");
        let r = fit(&Exponential::new(), &y_positive, &[1.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            RTOL,
            ATOL,
            "expon",
        );
        compare_params(&r.ml_se, &m.get("se").as_f64_vec(), RTOL, ATOL, "expon.se");
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "expon.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "expon.loglik",
        );
    }

    // --- lnorm (closed form) ------------------------------------------------
    {
        let m = models.get("lnorm");
        let r = fit(&LogNormal::new(), &y_positive, &[0.0, 1.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            RTOL,
            ATOL,
            "lnorm",
        );
        compare_params(&r.ml_se, &m.get("se").as_f64_vec(), RTOL, ATOL, "lnorm.se");
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "lnorm.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "lnorm.loglik",
        );
    }

    // --- weibull (optimizer) ------------------------------------------------
    {
        let m = models.get("weibull");
        let r = fit(&Weibull::new(), &y_positive, &[1.0, 1.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            OPT_RTOL,
            OPT_ATOL,
            "weibull",
        );
        // SE from the numerical Hessian fallback (see SE_RTOL docs).
        compare_params(
            &r.ml_se,
            &m.get("se").as_f64_vec(),
            SE_RTOL,
            SE_ATOL,
            "weibull.se",
        );
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "weibull.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "weibull.loglik",
        );
    }

    // --- gamma (optimizer; reference uses scale, Rust uses rate) ------------
    {
        let m = models.get("gamma");
        let r = fit(&Gamma::new(), &y_positive, &[1.0, 1.0]);
        let ref_params = m.get("params").as_f64_vec(); // [shape, scale]
                                                       // Convert reference scale -> rate = 1/scale.
        let expected = vec![ref_params[0], 1.0 / ref_params[1]];
        compare_params(&r.ml_params, &expected, OPT_RTOL, OPT_ATOL, "gamma");
        // SEs: reference SE is for scale; Rust SE is for rate. By the delta
        // method, SE(rate) = SE(scale) / scale^2.
        let ref_se = m.get("se").as_f64_vec();
        let expected_se = vec![ref_se[0], ref_se[1] / (ref_params[1] * ref_params[1])];
        // SE from the numerical Hessian fallback (see SE_RTOL docs).
        compare_params(&r.ml_se, &expected_se, SE_RTOL, SE_ATOL, "gamma.se");
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "gamma.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "gamma.loglik",
        );
    }

    // --- gumbel (optimizer) -------------------------------------------------
    {
        let m = models.get("gumbel");
        let r = fit(&Gumbel::new(), &y_general, &[10.0, 1.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            OPT_RTOL,
            OPT_ATOL,
            "gumbel",
        );
        // SE from the numerical Hessian fallback (see SE_RTOL docs).
        compare_params(
            &r.ml_se,
            &m.get("se").as_f64_vec(),
            SE_RTOL,
            SE_ATOL,
            "gumbel.se",
        );
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "gumbel.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "gumbel.loglik",
        );
    }

    // --- genextreme / GEV (optimizer) ---------------------------------------
    {
        let m = models.get("genextreme");
        let r = fit(&GenExtreme::new(), &y_general, &[10.0, 1.0, 0.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            OPT_RTOL,
            OPT_ATOL,
            "genextreme",
        );
        // SE from the numerical Hessian fallback (see SE_RTOL docs).
        compare_params(
            &r.ml_se,
            &m.get("se").as_f64_vec(),
            SE_RTOL,
            SE_ATOL,
            "genextreme.se",
        );
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "genextreme.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "genextreme.loglik",
        );
    }

    // --- genpareto / GPD (optimizer) ----------------------------------------
    {
        let m = models.get("genpareto");
        let r = fit(&GenPareto::new(), &y_positive, &[1.0, 0.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            OPT_RTOL,
            OPT_ATOL,
            "genpareto",
        );
        // SE from the numerical Hessian fallback (see SE_RTOL docs).
        compare_params(
            &r.ml_se,
            &m.get("se").as_f64_vec(),
            SE_RTOL,
            SE_ATOL,
            "genpareto.se",
        );
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "genpareto.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "genpareto.loglik",
        );
    }

    // --- norm_p1 (closed-form regression; reference centering/sigma quirks) --
    //
    // Two documented reference quirks make a naive comparison fail:
    //
    // 1. **Centering.** The reference `norm_p1_mlparams` reports the *uncentered*
    //    intercept from `lm(x~t)`, but its `expinfmat` (and hence its SEs) uses
    //    the *centered* predictor `t - mean(t)`, for which the intercept and
    //    slope are orthogonal. We therefore run the Rust model with
    //    `t0 = mean(t)` (matching the reference's centering) and convert the
    //    reference's uncentered intercept to the centered one:
    //    `centered = intercept + slope * mean(t)`.
    // 2. **Unbiased sigma.** The reference `expinfmat` uses the *unbiased* sd
    //    (`n-1` denominator) for `v3hat`, whereas the true MLE sigma is
    //    `sqrt((n-1)/n) * sd(resid)`. All three reference SEs scale linearly with
    //    sigma, so we multiply them by `sqrt((n-1)/n)` to convert to the MLE
    //    sigma convention that Rust uses.
    {
        let m = models.get("norm_p1");
        let n = y_general.len() as f64;
        let t_mean: f64 = t_p1.iter().sum::<f64>() / n;
        let model = NormalP1::new(t_p1.clone(), t_mean, 1.0);
        let r = fit(&model, &y_general, &[10.0, 0.0, 1.0]);
        let ref_params = m.get("params").as_f64_vec(); // [intercept, slope, sd(resid)]
        let sigma_factor = ((n - 1.0) / n).sqrt();
        // Centered intercept = uncentered intercept + slope * mean(t).
        let centered_intercept = ref_params[0] + ref_params[1] * t_mean;
        let mle_sigma = ref_params[2] * sigma_factor;
        let expected = vec![centered_intercept, ref_params[1], mle_sigma];
        compare_params(&r.ml_params, &expected, RTOL, ATOL, "norm_p1");
        // All three reference SEs scale by the same sigma factor.
        let ref_se = m.get("se").as_f64_vec();
        let expected_se = vec![
            ref_se[0] * sigma_factor,
            ref_se[1] * sigma_factor,
            ref_se[2] * sigma_factor,
        ];
        compare_params(&r.ml_se, &expected_se, RTOL, ATOL, "norm_p1.se");
        assert_close(r.aic, m.get("aic").as_f64(), RTOL, ATOL, "norm_p1.aic");
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "norm_p1.loglik",
        );
    }

    // --- genextreme_p1 (optimizer) ------------------------------------------
    //
    // W14: the reference `qgev_p1_cp` centers the predictor by its mean, so the
    // model is `mu_i = beta0 + beta1*(t_i - mean(t))`. The Rust model centers
    // automatically; `t0` only selects the prediction point (irrelevant to the
    // fit). The fixture is generated with the same centering.
    {
        let m = models.get("genextreme_p1");
        let model = GenExtremeP1::new(t_p1.clone(), 0.0, 1.0);
        let r = fit(&model, &y_general, &[10.0, 0.0, 1.0, 0.0]);
        compare_params(
            &r.ml_params,
            &m.get("params").as_f64_vec(),
            OPT_RTOL,
            OPT_ATOL,
            "genextreme_p1",
        );
        // SE from the numerical Hessian fallback (see SE_RTOL docs).
        compare_params(
            &r.ml_se,
            &m.get("se").as_f64_vec(),
            SE_RTOL,
            SE_ATOL,
            "genextreme_p1.se",
        );
        assert_close(
            r.aic,
            m.get("aic").as_f64(),
            RTOL,
            ATOL,
            "genextreme_p1.aic",
        );
        assert_close(
            r.loglik,
            m.get("loglik").as_f64(),
            RTOL,
            ATOL,
            "genextreme_p1.loglik",
        );
    }
}
